from pathlib import Path
terms=('derived','metadata','preview','excerpt','summary','wordcount','readingtime','recompute')
for p in Path('.').rglob('*'):
    if p.is_file() and '.git' not in p.parts and 'vendor' not in p.parts:
        try: s=p.read_text(errors='ignore')
        except: continue
        for i,line in enumerate(s.splitlines(),1):
            if any(t in line.lower().replace('_','').replace('-','') for t in terms):
                print(f'{p}:{i}:{line}')
PY

